import { useCallback, useEffect, useMemo, useState } from "react";

interface NativePanelProps { appName: string; installId: number; projectId: string }
interface CatalogApp { install_id: number; name: string; display_name?: string; description?: string; icon?: string; integration_roles?: IntegrationRole[] }
interface IntegrationRole { role: string; kind?: string; required?: boolean; compatible_slugs?: string[]; label?: string }
interface Connection { id: number; app_slug: string; name: string; status: string }
interface Integration { slug: string; name: string; description?: string; logo?: string; tool_count: number }
interface Tool { name: string; description?: string; inputSchema?: Record<string, any>; mock_response?: any }
interface Seed { app: string; tool: string; input: Record<string, any> }
interface Spec { version: number; ttl_seconds: number; app_install_ids: number[]; connection_ids: number[]; network_mode: string; integration_mode: string; integration_bindings: any[]; seeds: Seed[]; snapshot_id?: string }
interface Run { id: string; runtime_id: string; status: string; started_at: string; error?: string }
interface Environment { id: string; name: string; description?: string; desired_state: string; spec: Spec; active_run?: Run; runtime?: { status: string; apps: any[]; agents: any[]; expires_at: string } }
interface Catalog { apps: CatalogApp[]; connections: Connection[]; integrations: Integration[]; agents: any[]; snapshots: any[] }

const API = "/api/apps/environments/api";
let activeInstallId = 0;
let activeProjectId = "";
const emptySpec = (): Spec => ({ version: 1, ttl_seconds: 3600, app_install_ids: [], connection_ids: [], network_mode: "block", integration_mode: "mock", integration_bindings: [], seeds: [] });
async function request<T>(path: string, init?: RequestInit): Promise<T> { const url=new URL(API+path,window.location.origin);if(activeInstallId)url.searchParams.set("install_id",String(activeInstallId));if(activeProjectId)url.searchParams.set("project_id",activeProjectId);const r = await fetch(url.pathname+url.search, { ...init, headers: { "Content-Type": "application/json", ...(init?.headers || {}) } }); if (!r.ok) { const body = await r.json().catch(() => ({ error: r.statusText })); throw new Error(body.error || r.statusText) } return r.json() }

function SearchPicker<T>({ label, placeholder, items, selected, keyOf, titleOf, detailOf, onToggle }: { label: string; placeholder: string; items: T[]; selected: Set<string>; keyOf: (x:T)=>string; titleOf:(x:T)=>string; detailOf:(x:T)=>string; onToggle:(x:T)=>void }) {
  const [query,setQuery]=useState(""); const filtered=useMemo(()=>items.filter(x=>(titleOf(x)+" "+detailOf(x)).toLowerCase().includes(query.toLowerCase())).slice(0,8),[items,query,titleOf,detailOf]);
  return <div className="space-y-2"><label className="text-[11px] font-semibold uppercase text-text-dim">{label}</label><div className="relative"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={placeholder} className="w-full rounded-md border border-border bg-bg px-3 py-2 text-sm text-text outline-none focus:border-accent" />{query&&<button onClick={()=>setQuery("")} className="absolute right-2 top-1.5 h-6 w-6 text-text-dim hover:text-text" title="Clear search">×</button>}</div>{query&&<div className="max-h-60 overflow-auto rounded-md border border-border bg-surface shadow-xl">{filtered.length===0?<p className="p-3 text-xs text-text-dim">No matches</p>:filtered.map(x=>{const key=keyOf(x),active=selected.has(key);return <button key={key} onClick={()=>onToggle(x)} className="flex w-full items-center gap-3 border-b border-border px-3 py-2 text-left last:border-0 hover:bg-surface-hover"><span className={`flex h-4 w-4 shrink-0 items-center justify-center rounded border text-[10px] ${active?"border-accent bg-accent text-bg":"border-border"}`}>{active?"✓":""}</span><span className="min-w-0"><span className="block truncate text-sm text-text">{titleOf(x)}</span><span className="block truncate text-xs text-text-dim">{detailOf(x)}</span></span></button>})}</div>}</div>
}
function Chips<T>({ items, keyOf, labelOf, onRemove }: { items:T[]; keyOf:(x:T)=>string; labelOf:(x:T)=>string; onRemove:(x:T)=>void }) { return <div className="flex min-h-8 flex-wrap gap-1.5">{items.length===0?<span className="py-1 text-xs text-text-dim">Nothing selected</span>:items.map(x=><span key={keyOf(x)} className="inline-flex max-w-full items-center gap-1 rounded border border-border bg-surface px-2 py-1 text-xs text-text"><span className="truncate">{labelOf(x)}</span><button onClick={()=>onRemove(x)} className="text-text-dim hover:text-red" title="Remove">×</button></span>)}</div> }

function SeedEditor({ app, seed, onChange, onRemove }: { app:CatalogApp; seed:Seed; onChange:(s:Seed)=>void; onRemove:()=>void }) {
  const [tools,setTools]=useState<Tool[]>([]); const [advanced,setAdvanced]=useState(false); const [raw,setRaw]=useState(JSON.stringify(seed.input||{},null,2));
  useEffect(()=>{request<Tool[]>(`/catalog/apps/${app.install_id}/tools`).then(setTools).catch(()=>setTools([]))},[app.install_id]);
  const tool=tools.find(t=>t.name===seed.tool); const schema=tool?.inputSchema||{}; const props=schema.properties||{}; const required:string[]=schema.required||[]; const fields=Object.keys(props).sort((a,b)=>Number(required.includes(b))-Number(required.includes(a))||a.localeCompare(b));
  const setField=(key:string,value:string)=>{const type=props[key]?.type;let parsed:any=value;if(type==="number"||type==="integer")parsed=value===""?undefined:Number(value);if(type==="boolean")parsed=value==="true";const next={...seed.input};if(parsed===undefined||parsed==="")delete next[key];else next[key]=parsed;onChange({...seed,input:next});setRaw(JSON.stringify(next,null,2))};
  return <div className="rounded-md border border-border bg-bg"><div className="flex items-center gap-2 border-b border-border px-3 py-2"><span className="text-xs font-semibold text-text">{app.display_name||app.name}</span><select value={seed.tool} onChange={e=>onChange({...seed,tool:e.target.value,input:{}})} className="min-w-0 flex-1 bg-transparent text-xs text-text outline-none"><option value="">Select seed tool</option>{tools.map(t=><option key={t.name} value={t.name}>{t.name}</option>)}</select><button onClick={onRemove} className="h-6 w-6 text-text-dim hover:text-red" title="Remove seed">×</button></div>{tool&&<div className="space-y-3 p-3">{tool.description&&<p className="text-xs text-text-dim">{tool.description}</p>}<div className="grid gap-2 sm:grid-cols-2">{fields.filter(f=>advanced||required.includes(f)).map(f=><label key={f} className="space-y-1"><span className="text-[11px] text-text-dim">{f}{required.includes(f)&&<span className="text-red"> *</span>}</span>{props[f]?.type==="boolean"?<select value={String(seed.input?.[f]??false)} onChange={e=>setField(f,e.target.value)} className="w-full rounded border border-border bg-surface px-2 py-1.5 text-xs"><option value="false">False</option><option value="true">True</option></select>:<input value={typeof seed.input?.[f]==="object"?JSON.stringify(seed.input[f]):String(seed.input?.[f]??"")} onChange={e=>setField(f,e.target.value)} placeholder={props[f]?.description||props[f]?.type||"value"} className="w-full rounded border border-border bg-surface px-2 py-1.5 text-xs text-text outline-none focus:border-accent" />}</label>)}</div><div className="flex gap-3"><button onClick={()=>setAdvanced(!advanced)} className="text-xs text-accent hover:underline">{advanced?"Required fields only":"Show optional fields"}</button><button onClick={()=>setAdvanced(true)} className="text-xs text-text-dim hover:text-text">Raw JSON</button></div>{advanced&&<textarea value={raw} onChange={e=>setRaw(e.target.value)} onBlur={()=>{try{const value=JSON.parse(raw);onChange({...seed,input:value})}catch{}}} rows={4} className="w-full rounded border border-border bg-surface p-2 font-mono text-xs text-text outline-none focus:border-accent" />}</div>}</div>
}

function Builder({ initial, catalog, onClose, onSaved }: { initial?:Environment; catalog:Catalog; onClose:()=>void; onSaved:()=>void }) {
  const [name,setName]=useState(initial?.name||"");const [description,setDescription]=useState(initial?.description||"");const [spec,setSpec]=useState<Spec>(initial?.spec||emptySpec());const [appQuery,setAppQuery]=useState("");const [error,setError]=useState("");const [saving,setSaving]=useState(false);
  const selectedApps=catalog.apps.filter(x=>spec.app_install_ids.includes(x.install_id));const selectedConnections=catalog.connections.filter(x=>spec.connection_ids.includes(x.id));const fakeSlugs=new Set(spec.integration_bindings.filter(x=>x.expose_to_agents).map(x=>x.slug));const selectedFakes=catalog.integrations.filter(x=>fakeSlugs.has(x.slug));
  const suggested=useMemo(()=>{const slugs=new Set<string>();selectedApps.forEach(a=>(a.integration_roles||[]).forEach(r=>(r.compatible_slugs||[]).forEach(x=>slugs.add(x))));return catalog.integrations.filter(i=>slugs.has(i.slug))},[selectedApps,catalog.integrations]);
  const toggleApp=(x:CatalogApp)=>setSpec(v=>({...v,app_install_ids:v.app_install_ids.includes(x.install_id)?v.app_install_ids.filter(id=>id!==x.install_id):[...v.app_install_ids,x.install_id]}));const toggleConnection=(x:Connection)=>setSpec(v=>({...v,connection_ids:v.connection_ids.includes(x.id)?v.connection_ids.filter(id=>id!==x.id):[...v.connection_ids,x.id]}));const toggleFake=(x:Integration)=>setSpec(v=>{if(fakeSlugs.has(x.slug))return{...v,integration_bindings:v.integration_bindings.filter(b=>b.slug!==x.slug)};const roleBindings=selectedApps.flatMap(app=>(app.integration_roles||[]).filter(role=>(role.kind||"integration")!=="app"&&(role.compatible_slugs||[]).includes(x.slug)).map(role=>({app:app.name,role:role.role,slug:x.slug,name:`Mock ${x.name}`})));return{...v,integration_bindings:[...v.integration_bindings,{slug:x.slug,expose_to_agents:true,name:`Mock ${x.name}`},...roleBindings]}});
  const save=async(start:boolean)=>{setSaving(true);setError("");try{const d=await request<Environment>(initial?`/environments/${initial.id}`:"/environments",{method:initial?"PUT":"POST",body:JSON.stringify({id:initial?.id,name,description,spec,desired_state:initial?.desired_state||"stopped"})});if(start)await request(`/environments/${d.id}/start`,{method:"POST"});onSaved();onClose()}catch(e:any){setError(e.message)}finally{setSaving(false)}};
  const availableSeedApps=selectedApps.filter(a=>!spec.seeds.some(s=>s.app===a.name));
  return <div className="fixed inset-0 z-40 flex justify-end bg-black/40"><div className="flex h-full w-full max-w-2xl flex-col border-l border-border bg-bg shadow-2xl"><header className="flex h-14 items-center justify-between border-b border-border px-5"><div><h2 className="text-sm font-semibold text-text">{initial?"Edit environment":"New environment"}</h2><p className="text-xs text-text-dim">Project resources are cloned into an isolated runtime.</p></div><button onClick={onClose} className="h-8 w-8 text-xl text-text-dim hover:text-text" title="Close">×</button></header><div className="flex-1 space-y-6 overflow-y-auto p-5">
    <section className="grid gap-3 sm:grid-cols-2"><label className="space-y-1"><span className="text-[11px] font-semibold uppercase text-text-dim">Name</span><input value={name} onChange={e=>setName(e.target.value)} autoFocus className="w-full rounded-md border border-border bg-surface px-3 py-2 text-sm text-text outline-none focus:border-accent" /></label><label className="space-y-1"><span className="text-[11px] font-semibold uppercase text-text-dim">TTL</span><select value={spec.ttl_seconds} onChange={e=>setSpec({...spec,ttl_seconds:Number(e.target.value)})} className="w-full rounded-md border border-border bg-surface px-3 py-2 text-sm"><option value={900}>15 minutes</option><option value={3600}>1 hour</option><option value={14400}>4 hours</option><option value={86400}>24 hours</option></select></label><label className="space-y-1 sm:col-span-2"><span className="text-[11px] font-semibold uppercase text-text-dim">Description</span><input value={description} onChange={e=>setDescription(e.target.value)} className="w-full rounded-md border border-border bg-surface px-3 py-2 text-sm text-text outline-none focus:border-accent" /></label></section>
    <section className="space-y-3"><SearchPicker label="Apps" placeholder="Search installed apps" items={catalog.apps} selected={new Set(spec.app_install_ids.map(String))} keyOf={x=>String(x.install_id)} titleOf={x=>x.display_name||x.name} detailOf={x=>x.description||x.name} onToggle={toggleApp}/><Chips items={selectedApps} keyOf={x=>String(x.install_id)} labelOf={x=>x.display_name||x.name} onRemove={toggleApp}/></section>
    <section className="space-y-3"><SearchPicker label="Existing connections" placeholder="Search project connections" items={catalog.connections} selected={new Set(spec.connection_ids.map(String))} keyOf={x=>String(x.id)} titleOf={x=>x.name} detailOf={x=>x.app_slug} onToggle={toggleConnection}/><Chips items={selectedConnections} keyOf={x=>String(x.id)} labelOf={x=>`${x.name} · ${x.app_slug}`} onRemove={toggleConnection}/></section>
    <section className="space-y-3"><SearchPicker label="Fake connections" placeholder="Search integration catalog" items={catalog.integrations} selected={fakeSlugs} keyOf={x=>x.slug} titleOf={x=>x.name} detailOf={x=>x.description||`${x.tool_count} tools`} onToggle={toggleFake}/>{suggested.length>0&&<div className="flex flex-wrap items-center gap-1.5"><span className="text-xs text-text-dim">Suggested:</span>{suggested.filter(x=>!fakeSlugs.has(x.slug)).slice(0,6).map(x=><button key={x.slug} onClick={()=>toggleFake(x)} className="rounded border border-border px-2 py-1 text-xs text-text hover:border-accent">+ {x.name}</button>)}</div>}<Chips items={selectedFakes} keyOf={x=>x.slug} labelOf={x=>`Mock ${x.name}`} onRemove={toggleFake}/></section>
    <section className="space-y-3"><div className="flex items-center justify-between"><div><h3 className="text-[11px] font-semibold uppercase text-text-dim">Seed plan</h3><p className="text-xs text-text-dim">Runs in order after app sidecars are ready.</p></div><select value={appQuery} onChange={e=>{const app=catalog.apps.find(x=>x.name===e.target.value);if(app){setSpec(v=>({...v,seeds:[...v.seeds,{app:app.name,tool:"",input:{}}]}));setAppQuery("")}}} className="rounded border border-border bg-surface px-2 py-1.5 text-xs"><option value="">Add seed step</option>{availableSeedApps.map(a=><option key={a.install_id} value={a.name}>{a.display_name||a.name}</option>)}</select></div><div className="space-y-2">{spec.seeds.length===0?<div className="rounded-md border border-dashed border-border p-4 text-center text-xs text-text-dim">No seed steps</div>:spec.seeds.map((seed,i)=>{const app=catalog.apps.find(x=>x.name===seed.app);return app?<SeedEditor key={`${seed.app}-${i}`} app={app} seed={seed} onChange={next=>setSpec(v=>({...v,seeds:v.seeds.map((s,j)=>j===i?next:s)}))} onRemove={()=>setSpec(v=>({...v,seeds:v.seeds.filter((_,j)=>j!==i)}))}/>:null})}</div></section>
    <section className="grid gap-3 sm:grid-cols-2"><label className="space-y-1"><span className="text-[11px] font-semibold uppercase text-text-dim">Network</span><select value={spec.network_mode} onChange={e=>setSpec({...spec,network_mode:e.target.value})} className="w-full rounded border border-border bg-surface px-2 py-2 text-sm"><option value="block">Block external network</option><option value="record">Record traffic</option><option value="replay">Replay cassette</option><option value="passthrough">Allow network</option></select></label><label className="space-y-1"><span className="text-[11px] font-semibold uppercase text-text-dim">Integrations</span><select value={spec.integration_mode} onChange={e=>setSpec({...spec,integration_mode:e.target.value})} className="w-full rounded border border-border bg-surface px-2 py-2 text-sm"><option value="mock">Fake responses</option><option value="real">Real connections</option></select></label></section>{error&&<p className="rounded border border-red/40 bg-red/10 p-3 text-xs text-red">{error}</p>}
  </div><footer className="flex items-center justify-end gap-2 border-t border-border px-5 py-3"><button onClick={onClose} className="rounded-md border border-border px-4 py-2 text-sm text-text hover:bg-surface">Cancel</button><button disabled={saving||!name} onClick={()=>save(false)} className="rounded-md border border-border px-4 py-2 text-sm text-text hover:bg-surface disabled:opacity-40">Save</button><button disabled={saving||!name} onClick={()=>save(true)} className="rounded-md bg-accent px-4 py-2 text-sm font-semibold text-bg hover:bg-accent-hover disabled:opacity-40">Save and start</button></footer></div></div>
}

function Detail({ environment, catalog, onEdit, onRefresh }: { environment:Environment; catalog:Catalog; onEdit:()=>void; onRefresh:()=>void }) {
  const tabs=["Overview","Apps","Agents","Activity","Network","Snapshots"];const [tab,setTab]=useState("Overview");const [inspect,setInspect]=useState<any>(null);const [error,setError]=useState("");const run=environment.active_run;
  const load=useCallback(async()=>{if(!run)return;try{const agent=environment.runtime?.agents?.[0]?.alias||"";setInspect(await request(`/runs/${run.id}/inspect${agent?`?agent=${encodeURIComponent(agent)}`:""}`));setError("")}catch(e:any){setError(e.message)}},[run?.id,environment.runtime?.agents?.length]);
  useEffect(()=>{load();if(!run)return;const t=setInterval(load,5000);return()=>clearInterval(t)},[load,run?.id]);
  const runtime=inspect?.runtime||environment.runtime;const edge:any[]=inspect?.edge_calls||[];const telemetry:any[]=inspect?.telemetry||[];
  const snapshot=async()=>{try{await request(`/environments/${environment.id}/snapshot`,{method:"POST",body:JSON.stringify({description:`${environment.name} snapshot`})});onRefresh()}catch(e:any){setError(e.message)}};
  return <section className="mt-4 overflow-hidden rounded-md border border-border"><header className="flex items-center justify-between border-b border-border bg-surface px-4 py-3"><div><h2 className="text-sm font-semibold">{environment.name}</h2><p className="font-mono text-xs text-text-dim">{run?.runtime_id||environment.id}</p></div><button onClick={onEdit} className="rounded border border-border px-3 py-1.5 text-xs hover:bg-bg">Edit definition</button></header><nav className="flex overflow-x-auto border-b border-border px-2">{tabs.map(x=><button key={x} onClick={()=>setTab(x)} className={`border-b-2 px-3 py-2 text-xs ${tab===x?"border-accent text-text":"border-transparent text-text-dim hover:text-text"}`}>{x}</button>)}</nav>{error&&<p className="border-b border-border bg-red/10 px-4 py-2 text-xs text-red">{error}</p>}<div className="min-h-44 p-4">
    {tab==="Overview"&&<div className="grid gap-3 sm:grid-cols-4"><Metric label="Status" value={run?.status||"stopped"}/><Metric label="Apps" value={String(runtime?.apps?.length||0)}/><Metric label="Agents" value={String(runtime?.agents?.length||0)}/><Metric label="Edge calls" value={String(edge.length)}/><div className="sm:col-span-4 grid gap-2 text-xs text-text-dim sm:grid-cols-3"><span>Network: <b className="text-text">{environment.spec.network_mode}</b></span><span>Integrations: <b className="text-text">{environment.spec.integration_mode}</b></span><span>Expires: <b className="text-text">{runtime?.expires_at?new Date(runtime.expires_at).toLocaleString():"—"}</b></span></div></div>}
    {tab==="Apps"&&<CompactList empty="No apps in this environment" rows={(runtime?.apps||[]).map((x:any)=>({title:x.name,detail:`${x.kind||"sidecar"} · ${x.status||"unknown"}`}))}/>} 
    {tab==="Agents"&&<CompactList empty="No runtime agents" rows={(runtime?.agents||[]).map((x:any)=>({title:x.alias||x.source_name||`Agent ${x.id}`,detail:`${x.status||"unknown"}${x.source_agent_id?` · source ${x.source_agent_id}`:""}`}))}/>} 
    {tab==="Activity"&&<CompactList empty="No agent telemetry yet" rows={telemetry.slice().reverse().map((x:any)=>({title:x.type||"event",detail:`${x.thread_id||"main"} · ${x.time?new Date(x.time).toLocaleTimeString():""}`,code:typeof x.data==="string"?x.data:JSON.stringify(x.data||{})}))}/>} 
    {tab==="Network"&&<CompactList empty="No edge calls recorded" rows={edge.slice().reverse().map((x:any)=>({title:`${x.method||"GET"} ${x.host}${x.path||""}`,detail:`${x.status||0} · ${x.mocked?"mocked":x.blocked?"blocked":x.recorded?"recorded":x.allowed?"allowed":"observed"}`}))}/>} 
    {tab==="Snapshots"&&<div className="space-y-3"><div className="flex justify-end"><button disabled={!run} onClick={snapshot} className="rounded bg-accent px-3 py-1.5 text-xs font-semibold text-bg disabled:opacity-40">Create snapshot</button></div><CompactList empty="No snapshots" rows={(catalog.snapshots||[]).map((x:any)=>({title:x.description||x.id,detail:`${x.id} · ${x.created_at?new Date(x.created_at).toLocaleString():""}`}))}/></div>}
  </div></section>
}

function Metric({label,value}:{label:string;value:string}){return <div className="rounded border border-border bg-surface p-3"><span className="block text-[11px] uppercase text-text-dim">{label}</span><span className="mt-1 block truncate text-sm font-semibold">{value}</span></div>}
function CompactList({rows,empty}:{rows:{title:string;detail:string;code?:string}[];empty:string}){if(rows.length===0)return <p className="py-8 text-center text-xs text-text-dim">{empty}</p>;return <div className="divide-y divide-border">{rows.map((x,i)=><div key={`${x.title}-${i}`} className="py-2 first:pt-0 last:pb-0"><div className="text-xs font-medium text-text">{x.title}</div><div className="text-xs text-text-dim">{x.detail}</div>{x.code&&<pre className="mt-1 max-h-24 overflow-auto whitespace-pre-wrap rounded bg-bg p-2 text-[10px] text-text-dim">{x.code}</pre>}</div>)}</div>}

export default function EnvironmentsPanel({installId,projectId}:NativePanelProps) {
  activeInstallId=installId;activeProjectId=projectId;
  const [rows,setRows]=useState<Environment[]>([]);const [catalog,setCatalog]=useState<Catalog>({apps:[],connections:[],integrations:[],agents:[],snapshots:[]});const [builder,setBuilder]=useState<Environment|true|null>(null);const [selectedID,setSelectedID]=useState("");const [busy,setBusy]=useState("");const [error,setError]=useState("");
  const load=useCallback(async()=>{try{const [envs,cat]=await Promise.all([request<Environment[]>("/environments"),request<Catalog>("/catalog")]);setRows(envs);setCatalog(cat);setError("")}catch(e:any){setError(e.message)}},[]);useEffect(()=>{load();const t=setInterval(load,5000);return()=>clearInterval(t)},[load]);
  const act=async(id:string,action:string)=>{setBusy(id+action);try{await request(`/environments/${id}/${action}`,{method:"POST"});await load()}catch(e:any){setError(e.message)}finally{setBusy("")}};
  return <div className="h-full overflow-auto bg-bg text-text"><div className="w-full p-5"><header className="mb-5 flex flex-col items-start gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h1 className="text-xl font-semibold">Environments</h1><p className="text-sm text-text-dim">Isolated app sidecars, fake connections, agents, and virtualized edge traffic.</p></div><button onClick={()=>setBuilder(true)} className="rounded-md bg-accent px-3 py-2 text-sm font-semibold text-bg hover:bg-accent-hover">New environment</button></header>{error&&<div className="mb-4 flex items-center justify-between rounded-md border border-red/40 bg-red/10 px-3 py-2 text-xs text-red"><span>{error}</span><button onClick={()=>setError("")} title="Dismiss">×</button></div>}
    <div className="overflow-hidden rounded-md border border-border"><div className="hidden grid-cols-[minmax(0,1.6fr)_100px_1fr_150px] gap-3 border-b border-border bg-surface px-4 py-2 text-[11px] font-semibold uppercase text-text-dim sm:grid"><span>Environment</span><span>Status</span><span>Resources</span><span className="text-right">Actions</span></div>{rows.length===0?<div className="p-10 text-center"><p className="text-sm text-text-muted">No environments yet</p><p className="mt-1 text-xs text-text-dim">Create one from the apps and connections already installed in this project.</p></div>:rows.map(row=>{const running=!!row.active_run&&row.active_run.status==="running";return <div key={row.id} className={`grid grid-cols-1 items-center gap-2 border-b border-border px-4 py-3 last:border-0 hover:bg-surface/50 sm:grid-cols-[minmax(0,1.6fr)_100px_1fr_150px] sm:gap-3 ${selectedID===row.id?"bg-surface":""}`}><button onClick={()=>setSelectedID(row.id)} className="min-w-0 text-left"><span className="block truncate text-sm font-medium">{row.name}</span><span className="block truncate text-xs text-text-dim">{row.description||row.id}</span></button><span className={`text-xs font-medium ${running?"text-green":row.active_run?.status==="failed"?"text-red":"text-text-dim"}`}>{row.active_run?.status||"stopped"}</span><div className="flex min-w-0 flex-wrap gap-2 text-xs text-text-dim"><span>{row.spec.app_install_ids?.length||0} apps</span><span>·</span><span>{(row.spec.connection_ids?.length||0)+(row.spec.integration_bindings?.length||0)} connections</span><span>·</span><span>{row.spec.seeds?.length||0} seeds</span></div><div className="flex justify-start gap-1 sm:justify-end">{running?<><button onClick={()=>act(row.id,"snapshot")} disabled={!!busy} className="rounded border border-border px-2 py-1 text-xs hover:bg-surface" title="Create snapshot">Snapshot</button><button onClick={()=>act(row.id,"stop")} disabled={!!busy} className="rounded border border-border px-2 py-1 text-xs hover:border-red hover:text-red">Stop</button></>:<button onClick={()=>act(row.id,"start")} disabled={!!busy} className="rounded bg-accent px-3 py-1 text-xs font-semibold text-bg">Start</button>}</div></div>})}</div>{selectedID&&rows.find(x=>x.id===selectedID)&&<Detail environment={rows.find(x=>x.id===selectedID)!} catalog={catalog} onEdit={()=>setBuilder(rows.find(x=>x.id===selectedID)!)} onRefresh={load}/>} 
  </div>{builder&&<Builder initial={builder===true?undefined:builder} catalog={catalog} onClose={()=>setBuilder(null)} onSaved={load}/>}</div>
}
